```FILE: new_providers/Genspark/test_fresh.py
from __future__ import annotations

import importlib
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable
from unittest.mock import Mock

import pytest


MODULE_DIRECTORY = Path(__file__).resolve().parent
if str(MODULE_DIRECTORY) not in sys.path:
    sys.path.insert(0, str(MODULE_DIRECTORY))


def _import_provider() -> Any:
    try:
        return importlib.import_module("genspark_chat_public_URLS")
    except ModuleNotFoundError as error:
        if error.name != "genspark_chat_public_URLS":
            raise
        return importlib.import_module("genspark_chat")


provider = _import_provider()


@dataclass(frozen=True)
class FreshCheckResult:
    state: str
    balance: Any = None
    status_code: int | None = None


def run_fresh_check(
    session_factory: Callable[..., Any],
) -> FreshCheckResult:
    accounts = provider.load_accounts(provider.Config())
    if not accounts:
        return FreshCheckResult(state="no_accounts")

    account = accounts[-1]
    cookies = provider.do_login(account["email"], account["password"])
    if not cookies:
        return FreshCheckResult(state="login_failed")

    balance = provider.check_balance(cookies)

    session = session_factory(impersonate="chrome120")
    session.headers.update(
        {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "Chrome/120.0.0.0"
            ),
            "Content-Type": "application/json",
            "Origin": "https://www.genspark.ai",
            "Referer": "https://www.genspark.ai/",
        }
    )

    for name, value in cookies.items():
        session.cookies.set(
            name,
            value,
            domain="www.genspark.ai",
        )

    payload = {
        "models": ["gpt-4.1"],
        "run_with_another_model": False,
        "type": "super_agent",
        "messages": [{"role": "user", "content": "مرحبا"}],
        "user_s_input": "مرحبا",
        "session_state": {
            "steps": [],
            "messages": [{"role": "user", "content": "مرحبا"}],
        },
    }

    response = session.post(
        "https://www.genspark.ai/api/agent/ask_proxy",
        json=payload,
    )

    state = "unknown_response"
    for line in response.text.splitlines():
        if "ACTION_CREDIT_EXHAUSTED" in line:
            state = "credit_exhausted"
            break
        if "message_field_delta" in line:
            state = "success"
            break

    return FreshCheckResult(
        state=state,
        balance=balance,
        status_code=response.status_code,
    )


@pytest.fixture
def mocked_provider(monkeypatch: pytest.MonkeyPatch) -> dict[str, Mock]:
    config = object()
    mocks = {
        "config": Mock(return_value=config),
        "load_accounts": Mock(
            return_value=[
                {
                    "email": "first@example.test",
                    "password": "first-fake-password",
                },
                {
                    "email": "fresh@example.test",
                    "password": "fresh-fake-password",
                },
            ]
        ),
        "do_login": Mock(
            return_value={
                "session_id": "fake-session-id",
                "csrf_token": "fake-csrf-token",
            }
        ),
        "check_balance": Mock(return_value=42),
    }

    monkeypatch.setattr(provider, "Config", mocks["config"])
    monkeypatch.setattr(provider, "load_accounts", mocks["load_accounts"])
    monkeypatch.setattr(provider, "do_login", mocks["do_login"])
    monkeypatch.setattr(provider, "check_balance", mocks["check_balance"])

    return mocks


def create_mock_session(response_text: str, status_code: int = 200) -> tuple[Mock, Mock]:
    response = Mock(status_code=status_code, text=response_text)
    session = Mock()
    session.headers = {}
    session.post.return_value = response

    session_factory = Mock(return_value=session)
    return session_factory, session


def test_fresh_account_success(
    mocked_provider: dict[str, Mock],
) -> None:
    session_factory, session = create_mock_session(
        'data: {"type":"message_field_delta","delta":"مرحبا"}'
    )

    result = run_fresh_check(session_factory)

    assert result == FreshCheckResult(
        state="success",
        balance=42,
        status_code=200,
    )

    mocked_provider["config"].assert_called_once_with()
    mocked_provider["load_accounts"].assert_called_once_with(
        mocked_provider["config"].return_value
    )
    mocked_provider["do_login"].assert_called_once_with(
        "fresh@example.test",
        "fresh-fake-password",
    )
    mocked_provider["check_balance"].assert_called_once_with(
        {
            "session_id": "fake-session-id",
            "csrf_token": "fake-csrf-token",
        }
    )

    session_factory.assert_called_once_with(impersonate="chrome120")
    session.cookies.set.assert_any_call(
        "session_id",
        "fake-session-id",
        domain="www.genspark.ai",
    )
    session.cookies.set.assert_any_call(
        "csrf_token",
        "fake-csrf-token",
        domain="www.genspark.ai",
    )
    session.post.assert_called_once()

    request_url = session.post.call_args.args[0]
    request_payload = session.post.call_args.kwargs["json"]

    assert request_url == "https://www.genspark.ai/api/agent/ask_proxy"
    assert request_payload["models"] == ["gpt-4.1"]
    assert request_payload["user_s_input"] == "مرحبا"


def test_credit_exhausted_response(
    mocked_provider: dict[str, Mock],
) -> None:
    session_factory, session = create_mock_session(
        'data: {"error":"ACTION_CREDIT_EXHAUSTED"}'
    )

    result = run_fresh_check(session_factory)

    assert result.state == "credit_exhausted"
    assert result.balance == 42
    assert result.status_code == 200
    session.post.assert_called_once()


def test_unknown_stream_response(
    mocked_provider: dict[str, Mock],
) -> None:
    session_factory, session = create_mock_session(
        'data: {"type":"unrecognized_event"}',
        status_code=202,
    )

    result = run_fresh_check(session_factory)

    assert result == FreshCheckResult(
        state="unknown_response",
        balance=42,
        status_code=202,
    )
    session.post.assert_called_once()


def test_no_accounts_does_not_attempt_login_or_network(
    mocked_provider: dict[str, Mock],
) -> None:
    mocked_provider["load_accounts"].return_value = []
    session_factory = Mock()

    result = run_fresh_check(session_factory)

    assert result == FreshCheckResult(state="no_accounts")
    mocked_provider["do_login"].assert_not_called()
    mocked_provider["check_balance"].assert_not_called()
    session_factory.assert_not_called()


def test_failed_login_does_not_check_balance_or_use_network(
    mocked_provider: dict[str, Mock],
) -> None:
    mocked_provider["do_login"].return_value = {}
    session_factory = Mock()

    result = run_fresh_check(session_factory)

    assert result == FreshCheckResult(state="login_failed")
    mocked_provider["check_balance"].assert_not_called()
    session_factory.assert_not_called()
```

الاختبارات تغطي:

- اختيار آخر حساب وهمي.
- نجاح تسجيل الدخول والاستجابة.
- نفاد الرصيد.
- الاستجابة غير المعروفة.
- عدم وجود حسابات دون `sys.exit()`.
- فشل تسجيل الدخول.
- التأكد من عدم إنشاء جلسة شبكة في مسارات الفشل.

لتشغيل هذا الملف منفردًا:

```CMD
python -m pytest new_providers/Genspark/test_fresh.py -q
```

